#!/usr/bin/env python3
"""Steuerrechner: Annahmen mit Reglern von ungünstig (−2) über wahrscheinlich (0) bis günstig (+2).
26 unsichere Annahmen je mit drei Werten, Begründung und Quellen; Gesamtschalter (ungünstig, wahrscheinlich, günstig,
wie im Buch bisher), Einstellung in der Adresse (?annahmen=zins:-2,ki:1 oder ?annahmen=buch), helles Band in der
Schuldengrafik vom ungünstigen bis zum günstigen Fall. prognose("regler", …) rechnet mit stetigen Gewichten zwischen
dem ungünstigen und dem günstigen Szenario des Tragfähigkeitsberichts; die alten Fälle vorsichtig, mittel und
zuversichtlich sind seit der Recherche zur KI (17.11.2026) nicht mehr exakt nachgebildet; „wie im Buch“ rechnet weiter exakt. Vorschlag und Spannen:
https://claude.ai/artifact/Px68qW6AuBA7TwJz6LWugT (Faden „Szenarien im Rechner einstellbar machen“, 17.11.2026).
Läuft nach prognose-v36.py. Ein zweiter Lauf ändert nichts."""
p = 'steuerrechner/index.html'
s = open(p, encoding='utf-8').read()
if 'function szInit()' in s:
    raise SystemExit
def rep(a, b, n=1):
    global s
    assert s.count(a) == n, (s.count(a), a[:90])
    s = s.replace(a, b)

rep('.presets { display: flex; flex-wrap: wrap; gap: 8px; }',
    '.panel.szen { margin-bottom: 18px; gap: 12px; }\n.panel.szen h3 { margin: 0; }\n.szen .szgrp > .slider { margin-top: 14px; }\n.szr .row { flex-wrap: wrap; }\n.szr .row label { flex: 1 1 14em; }\n.szr .row output { margin-left: auto; text-align: right; }\n.szgrp:last-of-type { margin-bottom: 6px; }\n.szskala { display: flex; justify-content: space-between; font-size: .75rem; color: var(--muted); }\n.szwhy summary { cursor: pointer; font-size: .85rem; color: var(--accent); }\n.szwhy p { margin: 6px 0 0; }\n.presets { display: flex; flex-wrap: wrap; gap: 8px; }')
rep('    <p class="lead">Sieben Steuern fallen weg, neue Leistungen kommen dazu. Dafür gibt es die Steuer auf das, was ins Private fließt, und den Staatsanteil an Erbschaften. Dreh an den Stellschrauben und sieh, ob die Rechnung aufgeht. Die Änderungen wirken auch oben auf deinen Haushalt.</p>',
    '    <p class="lead">Sieben Steuern fallen weg, neue Leistungen kommen dazu. Dafür gibt es die Steuer auf das, was ins Private fließt, und den Staatsanteil an Erbschaften. Dreh an den Stellschrauben und sieh, ob die Rechnung aufgeht. Die Änderungen wirken auch oben auf deinen Haushalt.</p>\n    <div class="panel szen" id="szenWrap">\n      <h3>Annahmen: Wie sicher ist die Rechnung?</h3>\n      <p class="note">Wachstum, Zuwanderung, Zinsen, Sparen: Vieles weiß heute niemand genau. Jede dieser Annahmen hat einen wahrscheinlichen Wert und eine Spanne von ungünstig bis günstig. Stelle alle auf einmal um oder jede einzeln; die Ergebnisse unten rechnen sofort mit.</p>\n      <div id="szenBox"></div>\n    </div>')
rep('    ["Eigenes Haus frei, soweit beim Start bezahlt, bis Verkauf oder Erbgang", -ueb1.hf, 0],',
    '    ...(A.AusweichE ? [[`Ausweichen: Wer über 5.000 € im Monat ausgibt, kauft zum Teil weniger, anderswo oder später (Elastizität ${fmt(A.AusweichE, 2)}, wie im Buch ab Version 38; Annahme Nr. 15)`, -61.4 * A.AusweichE / 0.25, -65 * A.AusweichE / 0.25]] : []),\n    ["Eigenes Haus frei, soweit beim Start bezahlt, bis Verkauf oder Erbgang", -ueb1.hf, 0],')
rep('  const c = A.Sicherheit && !plan && sz === "zuversichtlich" ? { ...P[sz], ...P.zuversichtlichC7 } : P[sz];\n  const PB = [P.PBG, P.PBU, (P.PBG + P.PBU) / 2][c.grund - 1];\n  const Demo = [P.DemoG, P.DemoU, (P.DemoG + P.DemoU) / 2][c.grund - 1];\n  let d = A.Schuld, dprev = d, nprev = 0, g = P.TBZins0, b = Q.AusgBasis, dab = d; const out = [{ jahr: P.Start, v: d, mw: 0 }];',
    '  const c = sz === "regler" ? SZ_C : A.Sicherheit && !plan && sz === "zuversichtlich" ? { ...P[sz], ...P.zuversichtlichC7 } : P[sz];\n  // Gewicht zwischen ungünstigem (0) und günstigem Szenario (1) des Tragfähigkeitsberichts; grund 1 günstig, 2 ungünstig, 3 Mitte\n  const gw = c.gw ?? [1, 0, 0.5][c.grund - 1], dw = c.dw ?? gw;\n  const PB = P.PBU + (P.PBG - P.PBU) * gw;\n  const Demo = P.DemoU + (P.DemoG - P.DemoU) * dw;\n  let d = A.Schuld, dprev = d, nprev = 0, g = P.TBZins0, b = Q.AusgBasis, dab = d; const out = [{ jahr: P.Start, v: d, mw: 0 }];')
rep('    let gr = [wG, wU, (wG + wU) / 2][c.grund - 1];\n    if (reform && y >= P.ReformStart && y < P.ReformStart + P.WachsJahre) gr += c.wachs / P.WachsJahre;',
    '    let gr = wU + (wG - wU) * gw;\n    if (reform && y >= P.ReformStart && y < P.ReformStart + P.WachsJahre) gr += c.wachs / P.WachsJahre;')
rep('    if (c.ki && y >= P.KI.von && y < P.KI.von + P.KI.jahre) gr += P.KI.dg;\n    if (plan && y >= 2030 && y < 2045) gr += c.bild / 15;',
    '    if (y >= P.KI.von && y < P.KI.von + P.KI.jahre) gr += c.kiDg ?? (c.ki ? P.KI.dg : 0);\n    if (c.afDg && y >= 2030 && y < 2050) gr += c.afDg;   // autonomes Fahren, mit und ohne Reform\n    if (plan && y >= 2030 && y < 2045) gr += c.bild / 15;')
rep('  b.onclick = () => { Object.assign(A, structuredClone(A0)); sicherheitAnwenden(); renderKnobs(); updateAll(); };\n  box.append(b);',
    '  b.onclick = () => { Object.assign(A, structuredClone(A0)); sicherheitAnwenden(); szAnwenden(); renderKnobs(); updateAll(); };\n  box.append(b);')
rep('let szenario = "mittel", demoAus = false;\n$("demoAus").addEventListener("change", e => { demoAus = e.target.checked; updateGesamt(); });',
    'let szenario = "regler", demoAus = false;\n$("demoAus").addEventListener("change", e => { demoAus = e.target.checked; updateGesamt(); });')
rep('    if (szenario === "mittel") { const pz = planFall("zuversichtlich", pf), pv = planFall("vorsichtig", pf); const oz = prognose("zuversichtlich", "ohne", pf), ov = prognose("vorsichtig", "ohne", pf); reihen.forEach((r, i) => { r.pz = pz[i] ? pz[i].v : r.plan; r.pv = pv[i] ? pv[i].v : r.plan; r.oz = oz[i] ? oz[i].v : r.ohne; r.ov = ov[i] ? ov[i].v : r.ohne; }); }\n    if (demoAus) { // gleiche Rechnung ohne Reform, aber die Kosten für Rente, Pflege und Gesundheit bleiben auf dem Anteil am BIP von 2023',
    '    if (szenario === "regler") { const B = szBand(), pz = B[2].plan, pv = B[-2].plan, oz = B[2].ohne, ov = B[-2].ohne; reihen.forEach((r, i) => { r.pz = pz[i] ? pz[i].v : r.plan; r.pv = pv[i] ? pv[i].v : r.plan; r.oz = oz[i] ? oz[i].v : r.ohne; r.ov = ov[i] ? ov[i].v : r.ohne; }); }\n    if (demoAus) { // gleiche Rechnung ohne Reform, aber die Kosten für Rente, Pflege und Gesundheit bleiben auf dem Anteil am BIP von 2023')
rep('  const SZ = { vorsichtig: "Vorsichtig", mittel: "Mittel", zuversichtlich: "Zuversichtlich", basis: "Einfache Rechnung (Kapitel 6)" };\n  $("szenarien").innerHTML = Object.entries(SZ).map(([k, n]) => `<button type="button" class="chip" data-sz="${k}" aria-pressed="${k === szenario}">${n}</button>`).join("");',
    '  const SZ = { regler: "Mit den Annahmen oben", basis: "Einfache Rechnung (Kapitel 6)" };\n  $("szenarien").innerHTML = Object.entries(SZ).map(([k, n]) => `<button type="button" class="chip" data-sz="${k}" aria-pressed="${k === szenario}">${n}</button>`).join("");')
rep('    : `Mit den steigenden Kosten für Rente, Pflege und Gesundheit nach dem Tragfähigkeitsbericht des Finanzministeriums (2024). ${{ vorsichtig: "Vorsichtig: ungünstige Entwicklung, wenig zusätzliches Wachstum durch die Reform.", mittel: "Mittel: zwischen günstiger und ungünstiger Entwicklung, mittleres Wachstum durch die Reform.", zuversichtlich: "Zuversichtlich: günstige Entwicklung, mehr Wachstum durch die Reform." }[szenario]} Die Reform beginnt 2028. Der Zukunftsplan aus Kapitel 6 setzt dazu: Rente für 20 Jahre, Gesundheit, eine schlankere Verwaltung, Bildung, Kitas und Forschung, weniger Finanzhilfen, gesunde Ernährung, EU-Binnenmarkt und eine Ausgabenregel, solange der Staat Schulden hat. Die Schuldenregel: ab 2035 steigen die Schulden nicht mehr gegenüber dem Vorjahr, ab 2040 liegen sie nie über 63 % der Wirtschaftsleistung. Für den Kredit der ersten Jahre braucht es eine eigene Übergangsregel im Grundgesetz. Reicht der Plan nicht, steigt der Normalsatz der Mehrwertsteuer um die nötigen Punkte. Die höheren Ausgaben für Verteidigung (1,5 % der Wirtschaftsleistung) sind eingerechnet, bezahlt aus Kürzungen und dem Überschuss der Reform. Nach der Tilgung senkt die Hälfte des Überschusses die Steuern, die andere Hälfte wächst im Zukunftsfonds; unter null hat der Staat Vermögen.${A.Sicherheit ? " Mit Sicherheitszuschlag: die Verteidigung bis 2027 auf Kredit, danach aus Einsparungen und dem Sicherheitszuschlag." : ""}`;\n  if (szenario === "mittel") $("chartNote").textContent += " Die Linien zeigen den wahrscheinlichsten Verlauf. Das helle Band dahinter zeigt die Spanne vom vorsichtigen bis zum zuversichtlichen Fall, hellrot ohne Reform, hellgrün mit Zukunftsplan.";\n  drawChart(reihen);',
    '    : `Mit den steigenden Kosten für Rente, Pflege und Gesundheit nach dem Tragfähigkeitsbericht des Finanzministeriums (2024). Gerechnet mit den Annahmen oben: ${szStand()}. Die Reform beginnt 2028. Der Zukunftsplan aus Kapitel 6 setzt dazu: Rente für 20 Jahre, Gesundheit, eine schlankere Verwaltung, Bildung, Kitas und Forschung, weniger Finanzhilfen, gesunde Ernährung, EU-Binnenmarkt und eine Ausgabenregel, solange der Staat Schulden hat. Die Schuldenregel: ab 2035 steigen die Schulden nicht mehr gegenüber dem Vorjahr, ab 2040 liegen sie nie über 63 % der Wirtschaftsleistung. Für den Kredit der ersten Jahre braucht es eine eigene Übergangsregel im Grundgesetz. Reicht der Plan nicht, steigt der Normalsatz der Mehrwertsteuer um die nötigen Punkte. Die höheren Ausgaben für Verteidigung (1,5 % der Wirtschaftsleistung) sind eingerechnet, bezahlt aus Kürzungen und dem Überschuss der Reform. Nach der Tilgung senkt die Hälfte des Überschusses die Steuern, die andere Hälfte wächst im Zukunftsfonds; unter null hat der Staat Vermögen.${A.Sicherheit ? " Mit Sicherheitszuschlag: die Verteidigung bis 2027 auf Kredit, danach aus Einsparungen und dem Sicherheitszuschlag." : ""}`;\n  if (szenario === "regler") $("chartNote").textContent += " Die Linien zeigen den Verlauf mit den eingestellten Annahmen. Das helle Band dahinter zeigt die Spanne vom ungünstigen bis zum günstigen Fall, wenn alle Annahmen auf einmal so kommen, hellrot ohne Reform, hellgrün mit Zukunftsplan.";\n  drawChart(reihen);')
rep('  return pl;',
    '  return pl;\n}\n// Saldo-Pfad für die Prognose, wie in updateGesamt (mit Sicherheitsbeitrag ohne Verteidigung und Beitrag)\nfunction szPf(kr) {\n  if (!A.Sicherheit) return kr.rows.map(r => r.saldo);\n  const sic = { Verteidigung: A.Verteidigung, SubvAbbau: A.SubvAbbau, SichPkt: A.SichPkt, Sicherheit: A.Sicherheit };\n  Object.assign(A, { Verteidigung: 0, SubvAbbau: 0, SichPkt: 0, Sicherheit: 0 });\n  const gB = gesamt(), pf = kredit(gB.saldoS, gB.saldoL, 45, gB.s4).rows.map(r => r.saldo);\n  Object.assign(A, sic); return pf;\n}\n// Band: alle Annahmen ungünstig (−2) und alle günstig (+2)\nfunction szBand() {\n  const pos0 = { ...SZ_POS }, b0 = szBuch, res = {};\n  for (const s of [-2, 2]) { szAlle(s); szAnwenden(); const g = gesamt(), kr = kredit(g.saldoS, g.saldoL, 45, g.s4), pf = szPf(kr); res[s] = { plan: planFall("regler", pf), ohne: prognose("regler", "ohne", pf) }; }\n  Object.assign(SZ_POS, pos0); szBuch = b0; szAnwenden(); gesamt(); return res;')
rep('function sicherheitAnwenden() { if (A.Sicherheit) { const W = A.SicherheitWerte; Object.assign(A, { Verteidigung: W.Verteidigung, SubvAbbau: W.SubvAbbau, SichPkt: W.SichPkt, GSMwStJ: W.GSMwStJ, Grenze1: W.Grenze1, Grenze2: W.Grenze2 }); } }',
    'function sicherheitAnwenden() { if (A.Sicherheit) { const W = A.SicherheitWerte; Object.assign(A, { Verteidigung: W.Verteidigung, SubvAbbau: W.SubvAbbau, SichPkt: W.SichPkt, GSMwStJ: W.GSMwStJ, Grenze1: W.Grenze1, Grenze2: W.Grenze2 }); } }\n/* ---------- Annahmen: ungünstig, wahrscheinlich, günstig (Regler −2 … +2) ---------- */\n// Jede unsichere Annahme hat drei Werte: ungünstig (−2), wahrscheinlich (0), günstig (+2); ±1 liegt genau dazwischen.\n// Günstig heißt immer günstig für das Ergebnis (Staatskasse und Wohlstand). buch = der Wert, mit dem das Buch bisher rechnet.\nconst KI_ANTEIL = [0.0050678761785646945, 0.015204, 0.030408257071388167];   // KI-Anteil in Nr. 4 (Anhang C5, mit dem Carnegie-Effekt), zählt nicht doppelt, wenn der KI-Schub läuft\nconst SZ_C = {};      // Werte für die Prognose (prognose("regler", …))\nconst SZEN = [\n  { g: "A", nr: 1, k: "bev", lbl: "Bevölkerung und Arbeitsmarkt: Geburten, Zuwanderung, Erwerbstätigkeit", w: [0, 0.5, 1], buch: 0.5,\n    f: v => v <= 0.001 ? "ungünstiges Szenario des Ministeriums" : v >= 0.999 ? "günstiges Szenario des Ministeriums" : Math.abs(v - 0.5) < 0.001 ? "Mitte der beiden Szenarien" : v < 0.5 ? "zwischen Mitte und ungünstig" : "zwischen Mitte und günstig",\n    set: v => { SZ_C.gw = v; },\n    why: "Das Finanzministerium rechnet im Tragfähigkeitsbericht 2024 ein günstiges und ein ungünstiges Szenario, die sich bei Geburten, Zuwanderung, Erwerbstätigkeit und Produktivität unterscheiden. Ohne Reform liegen die Schulden 2070 dort bei 140 % und 365 % der Wirtschaftsleistung.",\n    q: [["Sechster Tragfähigkeitsbericht (BMF 2024)", "https://dserver.bundestag.de/btd/20/112/2011235.pdf"], ["FiFo-Bericht 33", "https://kups.ub.uni-koeln.de/73469/1/FiFo-Berichte_Nr_33_2024.pdf"], ["Destatis: Bevölkerungsvorausberechnung", "https://www.destatis.de/DE/Themen/Gesellschaft-Umwelt/Bevoelkerung/Bevoelkerungsvorausberechnung/annahmen_ergebnisse_16te_kBv.html"]] },\n  { g: "A", nr: 2, k: "alter", lbl: "Mehrkosten des Alterns bis 2070 (Rente, Pflege, Gesundheit)", w: [0.088, 0.0615, 0.035], buch: 0.0615,\n    f: v => "+" + pct(v, 1) + " der Wirtschaftsleistung",\n    set: v => { SZ_C.dw = (0.088 - v) / (0.088 - 0.035); },\n    why: "Spanne des Tragfähigkeitsberichts: 3,5 % im günstigen, 8,8 % im ungünstigen Szenario.",\n    q: [["Sechster Tragfähigkeitsbericht (BMF 2024)", "https://dserver.bundestag.de/btd/20/112/2011235.pdf"]] },\n  { g: "A", nr: 3, k: "zins", lbl: "Zins auf neue Bundesanleihen ab 2035", w: [0.05, 0.04, 0.03], buch: 0.04,\n    f: v => pct(v, 1) + " im Jahr",\n    set: v => { A.Zins = v; A.Prognose.ZinsNeu = [[2023, 0.027], [2035, v], [2070, v]]; },\n    why: "Heute rund 3,2 %. 3 bis 5 % ist die Spanne der letzten 20 Jahre ohne die Jahre mit Nullzins.",\n    q: [["Bundesbank: Renditen der Bundeswertpapiere", "https://www.bundesbank.de/resource/blob/964902/b6605dbe00daa0a816b46ad9b7ddb4cc/472B63F073F071307366337C94F8C870/2026-10-06-rendite-download.pdf"], ["Zeitreihe seit 2006", "https://kapitalmarktanzeiger.de/zeitreihen/bundesanleihe-10-jahre/"]] },\n  { g: "A", nr: 4, k: "anreize", lbl: "Mehr Wirtschaftsleistung durch die Anreize aus Kapitel 4 und 5, nach 20 Jahren", w: [0.013706719558586973 - KI_ANTEIL[0], 0.032492565155950748 - KI_ANTEIL[1], 0.07538457286086185 - KI_ANTEIL[2]], buch: 0.032492565155950748 - KI_ANTEIL[1],\n    f: v => "+" + pct(v, 1),\n    set: (v, s) => { SZ_C.w4 = v; SZ_C.pbx = szWert([0.001, 0.0025, 0.005], s); },\n    why: "Summe der Studienspannen in Anhang C5: Arbeit im Rentenalter, Bürgerjob, Weiterbildung, KI, Erben. Der bessere Primärsaldo läuft mit (0,1 / 0,25 / 0,5 % der Wirtschaftsleistung).",\n    q: [["Anhang C5", "../buch/anhang-c.html#c5"], ["OECD: KI in den G7", "https://www.suerf.org/publications/suerf-policy-notes-and-briefs/macroeconomic-productivity-gains-from-artificial-intelligence-in-g7-economies/"]] },\n  { g: "A", nr: 5, k: "ki", lbl: "KI-Schub, 2027 bis 2041, kommt auch ohne Reform", w: [0.0005, 0.0035, 0.01], buch: 0,\n    f: v => v < 1e-6 ? "kein Schub" : "+" + fmt(v * 100, 2) + " Punkte Wachstum im Jahr",\n    set: v => { SZ_C.kiDg = v; },\n    why: "Stand 2026: KI-Agenten lösen abgegrenzte Aufgaben am Computer schon besser als Menschen (86 % gegen 72 % im Test OSWorld), lange Aufgaben über eine Stunde aber erst zu 31 %. Die EZB rechnet für den Euroraum mit 0,2 bis 0,4 Punkten mehr Wachstum im Jahr, die OECD für Länder mit viel Büroarbeit mit 0,4 bis 1,3, IAB, BIBB und GWS für Deutschland mit 0,8. Acemoglu erwartet höchstens 0,07. Wahrscheinlich: 0,35 Punkte. Der Schub kommt mit und ohne Reform; was die Reform an schnellerer Einführung dazubringt, steht in Nr. 25.",\n    q: [["IAB-Forschungsbericht 23/2025", "https://doku.iab.de/forschungsbericht/2025/fb2325.pdf#page=27"], ["EZB: KI und der Euroraum (2026)", "https://www.ecb.europa.eu/press/key/date/2026/html/ecb.sp260323_1~1e06784a89.en.html"], ["KI-Agenten 2026: OSWorld, Übersicht", "https://www.noxia.co.uk/field-notes/agents-beat-humans-and-still-finish-30-percent"], ["OECD: KI in den G7", "https://www.suerf.org/publications/suerf-policy-notes-and-briefs/macroeconomic-productivity-gains-from-artificial-intelligence-in-g7-economies/"]] },\n  { g: "A", nr: 25, k: "kireform", lbl: "KI schneller in allen Betrieben, dank Berufscoach und KI-Lernguthaben (nur mit Reform), nach 20 Jahren", w: [0.005, 0.02, 0.05], buch: KI_ANTEIL[1],\n    f: v => "+" + pct(v, 1),\n    set: v => { SZ_C.w25 = v; },\n    why: "Deutschland nutzt KI langsam: Beschäftigte verbringen nicht einmal ein Drittel so viel Arbeitszeit mit KI wie in den USA, und rund die Hälfte sagt, bessere Schulung würde sie zur Nutzung bringen. Mit Berufscoach und Lernguthaben kommt die Einführung schneller; das zählt nur im Reformfall. Die EZB rechnet bei schneller statt langsamer Einführung mit rund 0,15 Punkten mehr Wachstum im Jahr, über 15 Jahre rund 2 %. Ungünstig: 0,5 %, günstig: Deutschland holt zu den Ländern mit schneller Einführung auf, 5 %.",\n    q: [["Anhang C5", "../buch/anhang-c.html#c5"], ["Fed St. Louis: KI-Nutzung Europa und USA (2026)", "https://www.stlouisfed.org/on-the-economy/2026/mar/mind-gap-ai-adoption-europe-us"], ["EZB-Blog: Was Beschäftigte berichten (2026)", "https://www.ecb.europa.eu/press/blog/date/2026/html/ecb.blog20260826~e1c1a89999.en.html"], ["Brynjolfsson u. a.: KI im Kundendienst", "https://www.nber.org/papers/w31161"], ["OECD: KI in den G7", "https://www.suerf.org/publications/suerf-policy-notes-and-briefs/macroeconomic-productivity-gains-from-artificial-intelligence-in-g7-economies/"]] },\n  { g: "A", nr: 26, k: "autofahr", lbl: "Autonomes Fahren, 2030 bis 2049, kommt auch ohne Reform, nach 20 Jahren", w: [0, 0.005, 0.01], buch: 0,\n    f: v => v < 1e-6 ? "kein Schub" : "+" + pct(v, 1),\n    set: v => { SZ_C.afDg = v / 20; },\n    why: "Fahrerlose Lkw, Busse und Taxis sparen Lohnkosten und Unfälle, Pendler gewinnen Zeit. Eine belastbare Studie für Deutschland gibt es noch nicht; eigene Schätzung: wahrscheinlich 0,5 % mehr Wirtschaftsleistung nach 20 Jahren. Günstig 1 %, weil ein Teil im günstigen KI-Schub (Nr. 5) schon steckt.",\n    q: [["Deutsche Bahn: Studie autonomes Fahren (2026)", "https://www.deutschebahn.com/resource/blob/13715340/75e27b85b32425f5bebd77b57c63e425/01-2026_Kurzfassung_Studie-Autonomes-Fahren_FINAL_neu01-data.pdf"], ["Bundesregierung: Strategie autonomes Fahren", "https://www.bmv.de/SharedDocs/DE/Publikationen/StV/die-zukunft-faehrt-autonom.pdf?__blob=publicationFile"]] },\n  { g: "A", nr: 6, k: "weitere", lbl: "Weitere Vorschläge: steuerfreie Gewinne im Betrieb, weniger Bürokratie, Fachkräfte, Gründungen", w: [0, 0.057750 - 0.032492565155950748 + 0.75 * 0.001, 0.12695009498140045 - 0.07538457286086185 + 0.030408257071388167 + 0.75 * 0.0055], buch: 0.057750 - 0.032492565155950748,\n    f: v => "+" + pct(v, 1),\n    set: v => { SZ_C.w6 = v; },\n    why: "Tabelle in Anhang C5, zusätzlich zu Nr. 4, nach Abzug der Überschneidungen. Dazu „Von Amerika lernen“: 10 % des Zuwachses der Verteidigungsausgaben gehen in Forschung (0 / 0,1 / 0,3 %), die sechs weiteren Punkte nur im günstigen Fall (bis 0,25 %), je nach dem Abschlag von einem Viertel. Ungünstig: Die Vorschläge bringen nichts zusätzlich.",\n    q: [["Anhang C5", "../buch/anhang-c.html#c5"], ["ifo: Kosten der Bürokratie", "https://www.ifo.de/pressemitteilung/2024-11-14/buerokratie-deutschland-kostet-jaehrlich-146-milliarden-euro"], ["OECD: Forschung und Produktivität", "https://www.oecd.org/science-and-technology/r-d-and-productivity-growth_652870318341"]] },\n  { g: "A", nr: 7, k: "plan", lbl: "Zukunftsplan: Bildung, Kitas, Forschung, gesunde Ernährung, EU-Binnenmarkt", w: [0, 1, 2], buch: 1,\n    f: v => ["schwache Wirkung", "mittlere Wirkung", "starke Wirkung"][Math.round(v)] || "dazwischen",\n    set: (v, s) => { for (const [k, w] of Object.entries({ bild: [0.0025, 0.005, 0.01], ern: [0.001, 0.002, 0.003], binnen: [0.01, 0.02, 0.035], kita: [0.001, 0.002, 0.003], forsch: [0.004, 0.007, 0.015] })) SZ_C[k] = szWert(w, s); },\n    why: "Die Werte der Hebel im Zukunftsplan (Anhang C9), je mit einer kleinen, mittleren und großen Wirkung.",\n    q: [["Anhang C9", "../buch/anhang-c.html#c9"], ["IWF zum EU-Binnenmarkt", "https://www.imf.org/en/publications/fandd/issues/2025/06/europes-integration-imperative-alfred-kammer"]] },\n  { g: "A", nr: 8, k: "wachstum", lbl: "Wachstum der Wirtschaft in Euro (nominal), Blatt Kredit", w: [0.02, 0.025, 0.03], buch: 0.025,\n    f: v => pct(v, 1) + " im Jahr",\n    set: v => { A.Wachstum = v; },\n    why: "2025 waren es 3,3 %. Inflationsziel 2 % plus reales Wachstum von 0 bis 1 %.",\n    q: [["Statistisches Bundesamt: Inlandsprodukt", "https://www.destatis.de/DE/Themen/Wirtschaft/Volkswirtschaftliche-Gesamtrechnungen-Inlandsprodukt/Tabellen/lrvgr02.html"]] },\n  { g: "A", nr: 24, k: "aufbruch", lbl: "Aufbruch und Synergien: mehr Investitionen aus höherer Ersparnis, Technik, Gründungen, Beteiligungen", w: [-0.01, 0, 0.03], buch: 0,\n    f: v => (v > 0 ? "+" : v < 0 ? "−" : "") + pct(Math.abs(v), 1) + " nach 20 Jahren",\n    set: v => { SZ_C.w24 = v; },\n    why: "Simulationen für die USA finden beim Umstieg auf eine Steuer auf den Konsum langfristig bis zu 9 % mehr Wirtschaftsleistung, vor allem durch mehr Kapital; ein Teil davon steckt schon in Nr. 6. Schwach belegt: Eine Aufbruchstimmung lässt sich nicht messen, deshalb ist die Mitte 0.",\n    q: [["Altig, Auerbach, Kotlikoff u. a. (AER 2001)", "https://econpapers.repec.org/RePEc:aea:aecrev:v:91:y:2001:i:3:p:574-595"]] },\n\n  { g: "B", nr: 9, k: "sparen", lbl: "Sparen nach Einkommen: welcher Teil eines Plus gespart wird", w: [1.6, 1, 0.6], buch: 1,\n    f: v => { const r = sparQuoten(v); return `${pct(r.mittel, 0)} gespart (unten ${pct(r.unten, 0)}, oben ${pct(r.oben, 0)})`; },\n    set: v => { for (const k of ["GS", "30", "60", "100", "Ueber", "Rent"]) A["VhSpar" + k] = Math.min(0.95, A0["VhSpar" + k] * v); },\n    why: "Wer mehr verdient, spart von zusätzlichem Geld mehr: im Modell 0 % in der Grundsicherung bis 57 % bei hohen Einkommen, im Mittel rund ein Viertel. Studien finden im ersten Jahr im Mittel gut die Hälfte ausgegeben; ungünstig sparen alle Gruppen 60 % mehr, günstig 40 % weniger.",\n    q: [["Fagereng, Holm, Natvik (2021)", "https://econpapers.repec.org/RePEc:aea:aejmac:v:13:y:2021:i:4:p:1-54"], ["Jappelli, Pistaferri (2014)", "https://econpapers.repec.org/RePEc:aea:aejmac:v:6:y:2014:i:4:p:107-36"], ["Dynan, Skinner, Zeldes: Do the Rich Save More? (2004)", "https://econpapers.repec.org/RePEc:ucp:jpolec:v:112:y:2004:i:2:p:397-444"], ["EVS 2018", "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/DEHeft_derivate_00057921/2152604189004_korr19112020.pdf"]] },\n  { g: "B", nr: 11, k: "minusSofort", lbl: "Wer weniger hat: Teil, um den er gleich weniger einkauft", w: [0.5, 0.25, 0.1], buch: 0.25,\n    f: v => pct(v, 0),\n    set: v => { A.VhMinusSofort = v; },\n    why: "Wer viel hat, ändert seinen Konsum wenig. 50 % rechnet Anhang C8.",\n    q: [["Jappelli, Pistaferri (2014)", "https://econpapers.repec.org/RePEc:aea:aejmac:v:6:y:2014:i:4:p:107-36"], ["Anhang C8", "../buch/anhang-c.html#c8"]] },\n  { g: "B", nr: 12, k: "minusSpaeter", lbl: "Wer weniger hat: später weniger Konsum je fehlendem Euro Vermögen", w: [0.06, 0.04, 0], buch: 0.04,\n    f: v => pct(v, 0) + " im Jahr",\n    set: v => { A.VhMinusSpaeter = v; },\n    why: "Große Vermögen werden selten aufgebraucht; mit 0 % wird nur weniger vererbt (Anhang C8).",\n    q: [["Anhang C2 und C8", "../buch/anhang-c.html#c8"]] },\n  { g: "B", nr: 13, k: "konsum", lbl: "Konsum insgesamt nach der Umstellung", w: [-0.05, 0, 0.01], buch: 0,\n    f: v => (v > 0 ? "+" : v < 0 ? "−" : "") + pct(Math.abs(v), 0),\n    set: v => { A.Konsum = A0.Konsum * (1 + v); },\n    why: "Der empfindlichste Wert: 5 % weniger Konsum kostet im ersten Jahr rund 100 Mrd. €. Eine belastbare Studie für die Spanne fehlt noch.",\n    q: [["Anhang C8", "../buch/anhang-c.html#c8"]] },\n  { g: "B", nr: 14, k: "gini", lbl: "Wie ungleich der Konsum verteilt ist", w: [sigmaAusGini(0.28), A0.Sigma, sigmaAusGini(0.33)], buch: A0.Sigma,\n    f: v => "Gini " + fmt(2 * normCdf(v / Math.SQRT2) - 1, 2),\n    set: v => { A.Sigma = v; },\n    why: "Ungleicher heißt hier günstig, weil die Ausgabensteuer oben mehr bringt. Spanne wie in Anhang C8.",\n    q: [["EVS 2018", "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/DEHeft_derivate_00057921/2152604189004_korr19112020.pdf"], ["ifo Schnelldienst 2/2020", "https://www.ifo.de/DocDL/sd-2020-02-niehues-stockhausen-etal-ungleichheit-2020-02-12_0.pdf"]] },\n  { g: "B", nr: 15, k: "ausweich", lbl: "Ausweichen der Reichen: wer über 5.000 € im Monat ausgibt, kauft weniger, anderswo oder später", w: [0.4, 0.25, 0.1], buch: 0,\n    f: v => v < 1e-6 ? "nicht eingerechnet" : "Elastizität " + fmt(v, 2) + ", rund " + fmt(61.4 * v / 0.25) + " Mrd. € am Start",\n    set: v => { A.AusweichE = v; },\n    why: "Das Buch rechnet seit Version 38 mit einer Elastizität von 0,25: Am Start fehlen dadurch rund 61 Mrd. €, 2070 rund 65 Mrd. €. Studien zur Reaktion hoher Einkommen auf Steuern finden meist 0,1 bis 0,4. Wegzug wegen Steuern ist bei Millionären selten.",\n    q: [["Saez, Slemrod, Giertz: The Elasticity of Taxable Income (2012)", "https://econpapers.repec.org/RePEc:aea:jeclit:v:50:y:2012:i:1:p:3-50"], ["Kleven u. a.: Taxation and Migration (2020)", "https://www.aeaweb.org/doi/10.1257/jep.34.2.119"], ["Young u. a.: Millionaire Migration (2016)", "https://inequality.stanford.edu/node/7506"]] },\n\n  { g: "C", nr: 16, k: "erbvol", lbl: "Erbschaften und Schenkungen im Jahr", w: [300, 350, 400], buch: 350,\n    f: v => fmt(v) + " Mrd. €",\n    set: v => { A.ErbVol = v; },\n    why: "Studienspanne des DIW: 300 bis 400 Mrd. € im Jahr.",\n    q: [["DIW: bis zu 400 Mrd. € im Jahr", "https://www.diw.de/de/diw_01.c.560993.de/in_deutschland_werden_zwischen_2012_und_2027_bis_zu_400__mil___d_vererbt_werden__gut_ein_viertel_mehr_als_bisher_angenommen.html"], ["DIW Wochenbericht 5/2021", "https://www.diw.de/de/diw_01.c.809832.de/publikationen/wochenberichte/2021_05_1/haelfte_aller_erbschaften_und_schenkungen_geht_an_die_reichsten_zehn_prozent_aller_beguenstigten.html"]] },\n  { g: "C", nr: 17, k: "real", lbl: "Teil des Staatsanteils an Erbschaften, der langfristig im Jahr in der Kasse ankommt", w: [0.25, 0.5, 0.75], buch: 0.5,\n    f: v => pct(v, 0),\n    set: v => { A.RealLang = v; },\n    why: "Der Rest bleibt in Betrieben und Anlagen als Anteil der Gemeinschaft. 25 % rechnet Anhang C8.",\n    q: [["Anhang C2 und C8", "../buch/anhang-c.html#c8"]] },\n  { g: "C", nr: 18, k: "fonds", lbl: "Ertrag des Zukunftsfonds nach Inflation", w: [0.01, 0.03, 0.045], buch: 0.03,\n    f: v => pct(v, 1) + " im Jahr",\n    set: v => { A.Prognose.Plan.Rendite = (1 + v) * (1 + A.Prognose.Infl) - 1; },\n    why: "Spanne breit gestreuter Aktien über lange Zeiträume, nach Inflation.",\n    q: [["DAI: DAX-Rendite-Dreieck", "https://www.dai.de/fileadmin/user_upload/251231_DAX-Rendite-Dreieck_50_Jahre_Web.pdf"]] },\n  { g: "C", nr: 19, k: "haus", lbl: "Wertzuwachs der Häuser (Anteil der Gemeinschaft)", w: [0.015, 0.025, 0.035], buch: 0.015,\n    f: v => pct(v, 1) + " im Jahr",\n    set: v => { A.AntWert = v; },\n    why: "2010 bis 2025 gut 4 % im Jahr. Die Annahme wirkt in zwei Richtungen: günstig für den Staat, ungünstig für den Eigentümer, dessen Anteil bei einem Einbau teurer abzulösen ist. Der Regler folgt der Staatskasse.",\n    q: [["Anhang C10", "../buch/anhang-c.html#ann-AntWert"]] },\n\n  { g: "D", nr: 20, k: "verw", lbl: "Einsparungen in der Verwaltung durch KI und Automatisierung", w: [15 / 36, 1, 76 / 36], buch: 1,\n    f: v => v === 1 ? "wie im Buch, rund 12 % weniger Stellen" : pct(v, 0) + " davon",\n    set: (v, s) => { A.VerwZiel = A0.VerwZiel * v; A.BeamtKI = A0.BeamtKI * v; SZ_C.w20 = s == null ? 0 : szWert([0.001, 0.005, 0.01], s); },\n    why: "Recherche vom 17.11.2026: Von rund 5,4 Mio. Stellen im öffentlichen Dienst lassen sich mit KI und Automatisierung wahrscheinlich 12 % einsparen, netto nach den laufenden KI-Kosten rund 36 Mrd. € im Jahr, voll erreicht 2043. Ungünstig 5 % (15 Mrd. €), günstig 25 % (76 Mrd. €, voll 2040). Heute lösen KI-Agenten kurze Aufgaben am Computer schon besser als Menschen, lange Vorgänge aber erst zu einem Drittel. Wer in der Verwaltung nicht mehr gebraucht wird, arbeitet in Betrieben: 270.000 / 650.000 / 800.000 Menschen, nach Abzug der Überschneidung mit den Fachkräften 0,1 / 0,5 / 1,0 % mehr Wirtschaftsleistung nach 20 Jahren, nur mit Reform.",\n    q: [["ifo: Kosten der Bürokratie", "https://www.ifo.de/pressemitteilung/2024-11-14/buerokratie-deutschland-kostet-jaehrlich-146-milliarden-euro"], ["Anhang C8", "../buch/anhang-c.html#c8"]] },\n  { g: "D", nr: 21, k: "rente", lbl: "Kosten von Rente und Pflege aus der Steuer", w: [1.1, 1, 0.95], buch: 1,\n    f: v => v === 1 ? "wie im Buch" : (v > 1 ? "+" : "−") + pct(Math.abs(v - 1), 0),\n    set: v => { A.RVPVKost = A0.RVPVKost * v; },\n    why: "10 % mehr rechnet Anhang C8.",\n    q: [["Anhang C8", "../buch/anhang-c.html#c8"]] },\n  { g: "D", nr: 22, k: "avk", lbl: "Kosten des Altvermögenskontos", w: [2, 1, 0.8], buch: 1,\n    f: v => v === 1 ? "wie im Buch" : fmt(v, 1) + "-fach",\n    set: v => { A.AltUeb = A0.AltUeb * v; if (A0.AVKGrenzeF != null) A.AVKGrenzeF = A0.AVKGrenzeF * v; },\n    why: "Doppelt so viel rechnet Anhang C8.",\n    q: [["Anhang C8", "../buch/anhang-c.html#c8"]] },\n  { g: "D", nr: 23, k: "zinsalt", lbl: "Zins auf die alten Staatsschulden", w: [0.04, 0.025, 0.02], buch: 0.025,\n    f: v => pct(v, 1) + " im Jahr",\n    set: v => { A.ZinsAlt = v; },\n    why: "4 % rechnet Anhang C8.",\n    q: [["Bundesbank: Maastricht-Schuldenstand", "https://www.bundesbank.de/de/statistiken/oeffentliche-finanzen/maastricht-defizit-und-schuldenstand"]] },\n];\nconst SZ_GRUPPEN = { A: "Bevölkerung, Wachstum und Zinsen", B: "Wie die Haushalte reagieren", C: "Erbe und Vermögen", D: "Staat und Verwaltung" };\nconst SZ_STUFE = { "-2": "ungünstig", "-1": "eher ungünstig", "0": "wahrscheinlich", "1": "eher günstig", "2": "günstig" };\nlet SZ_POS = Object.fromEntries(SZEN.map(r => [r.k, 0])), szBuch = false;\n\nfunction szWert(w, s) { const [lo, mid, hi] = w; return s < 0 ? mid + (lo - mid) * (-s / 2) : mid + (hi - mid) * (s / 2); }\nfunction sigmaAusGini(G) { return Math.SQRT2 * normsinv((G + 1) / 2); }\nfunction sparQuoten(f) {\n  const g = ["GS", "30", "60", "100", "Ueber", "Rent"], q = k => Math.min(0.95, A0["VhSpar" + k] * f);\n  return { unten: q("GS"), oben: q("Ueber"), mittel: g.reduce((a, k) => a + q(k) * A0["VhGew" + k], 0) / g.reduce((a, k) => a + A0["VhGew" + k], 0) };\n}\nfunction szAnwenden() {\n  for (const r of SZEN) { const s = SZ_POS[r.k]; r.set(szBuch ? r.buch : szWert(r.w, s), szBuch ? null : s); }\n  if (szBuch) { SZ_C.pbx = 0.0025; for (const [k, v] of Object.entries({ bild: 0.005, ern: 0.002, binnen: 0.02, kita: 0.002, forsch: 0.007 })) SZ_C[k] = v; }\n  // Wachstum durch die Reform: Anreize + weitere Vorschläge + Aufbruch + schnellere KI (Nr. 25). Der KI-Schub (Nr. 5) kommt auch ohne Reform als Sockel;\n  // die schnellere Einführung durch die Reform (Nr. 25) zählt zusätzlich, nur im Reformfall\n  SZ_C.wachs = SZ_C.w4 + SZ_C.w6 + SZ_C.w24 + SZ_C.w25 + (SZ_C.w20 || 0);   // Nr. 20: frei gewordene Verwaltungskräfte arbeiten in Betrieben\n}\n// Gesamtschalter: alle Regler auf eine Stufe\nfunction szAlle(s) {\n  szBuch = false; for (const r of SZEN) SZ_POS[r.k] = s;\n}\nfunction szStand() {\n  if (szBuch) return "Wie im Buch bisher";\n  const v = Object.values(SZ_POS), alle = v.every(x => x === v[0]);\n  return alle ? ({ "-2": "Ungünstiger Fall", "0": "Wahrscheinlicher Fall", "2": "Günstiger Fall" }[v[0]] || "Alle " + SZ_STUFE[v[0]]) : `Eigene Einstellung (${v.filter(x => x !== 0).length} Annahmen geändert)`;\n}\nfunction szUrl() {\n  try {\n    const p = new URLSearchParams(location.search), geaendert = SZEN.filter(r => SZ_POS[r.k] !== 0).map(r => r.k + ":" + SZ_POS[r.k]).join(",");\n    if (szBuch) p.set("annahmen", "buch"); else if (geaendert) p.set("annahmen", geaendert); else p.delete("annahmen");\n    const qs = p.toString(); history.replaceState(null, "", location.pathname + (qs ? "?" + qs : "") + location.hash);\n  } catch (e) {}\n}\nfunction szLesen() {\n  try {\n    const a = new URLSearchParams(location.search).get("annahmen"); if (!a) return;\n    if (a === "buch") { szBuch = true; return; }\n    for (const t of a.split(",")) { const [k, s] = t.split(":"); if (k in SZ_POS) SZ_POS[k] = clamp(Math.round(+s) || 0, -2, 2); }\n  } catch (e) {}\n}\n// Welche Annahmen bewegen das Ergebnis am meisten? Staatsschulden 2070 mit Zukunftsplan, je Annahme ungünstig gegen günstig\nfunction szWirkung() {\n  const pos0 = { ...SZ_POS }, buch0 = szBuch, ziel = () => { szAnwenden(); abgeleitet(); const g = gesamt(), kr = kredit(g.saldoS, g.saldoL, 45, g.s4); return prognose("regler", "plan", kr.rows.map(r => r.saldo)).at(-1).v; };\n  szBuch = false; const out = [];\n  for (const r of SZEN) { SZ_POS[r.k] = -2; const lo = ziel(); SZ_POS[r.k] = 2; const hi = ziel(); SZ_POS[r.k] = pos0[r.k]; out.push({ r, d: lo - hi }); }\n  Object.assign(SZ_POS, pos0); szBuch = buch0; szAnwenden(); abgeleitet();\n  return out.sort((a, b) => b.d - a.d);\n}\nfunction szRender() {\n  const box = $("szenBox"); if (!box) return;\n  const knopf = (s, n) => `<button type="button" class="chip" data-alle="${s}" aria-pressed="${!szBuch && Object.values(SZ_POS).every(x => x === s)}">${n}</button>`;\n  let h = `<div class="presets" role="group" aria-label="Alle Annahmen einstellen">${knopf(-2, "Ungünstig")}${knopf(0, "Wahrscheinlich")}${knopf(2, "Günstig")}<button type="button" class="chip" data-buch="1" aria-pressed="${szBuch}">Wie im Buch bisher</button></div>`;\n  h += `<p class="note" id="szStand"></p>`;\n  h += `<details class="more" id="szWirkBox"><summary>Welche Annahmen am meisten bewegen</summary><p class="note" id="szWirk">wird gerechnet …</p></details>`;\n  for (const [g, titel] of Object.entries(SZ_GRUPPEN)) {\n    h += `<details class="more szgrp"><summary>${titel}</summary>`;\n    for (const r of SZEN.filter(x => x.g === g)) {\n      h += `<div class="slider szr"><div class="row"><label for="sz_${r.k}">${r.nr}. ${r.lbl}</label><output id="szo_${r.k}"></output></div>`\n        + `<input type="range" id="sz_${r.k}" min="-2" max="2" step="1" value="${SZ_POS[r.k]}" aria-valuetext="${SZ_STUFE[SZ_POS[r.k]]}">`\n        + `<div class="szskala"><span>ungünstig</span><span>wahrscheinlich</span><span>günstig</span></div>`\n        + `<details class="szwhy"><summary>Warum diese Spanne?</summary><p class="note">Ungünstig: ${r.f(r.w[0])} · wahrscheinlich: ${r.f(r.w[1])} · günstig: ${r.f(r.w[2])}. Das Buch rechnete bisher mit ${r.f(r.buch)}.</p><p class="note">${r.why}</p><p class="note">Quellen: ${r.q.map(([n, u]) => `<a href="${u}" target="_blank" rel="noopener">${n}</a>`).join(" · ")}</p></details></div>`;\n    }\n    h += `</details>`;\n  }\n  h += `<p class="note">Ungünstig und günstig sind die Ränder der Spanne, in der das Ergebnis etwa in 9 von 10 Fällen liegt. Günstig heißt immer günstig für die Staatskasse und den Wohlstand. Die Rechnung für deinen Haushalt oben hängt an keiner dieser Annahmen.</p>`;\n  box.innerHTML = h;\n  box.querySelectorAll("[data-alle]").forEach(b => b.onclick = () => {\n    szAlle(+b.dataset.alle);\n    // Energie und Auto (Kasten aus energie-kasten.py): derselbe Fall, wirkt nur auf den eigenen Haushalt\n    const ef = document.getElementById("e_fall"), fall = { "-2": "ung", "0": "wahr", "2": "guen" }[b.dataset.alle]; if (ef && fall) ef.value = fall;\n    szNeu();\n  });\n  box.querySelector("[data-buch]").onclick = () => { szBuch = true; szNeu(); };\n  for (const r of SZEN) $("sz_" + r.k).oninput = e => { szBuch = false; SZ_POS[r.k] = +e.target.value; szNeu(false); };\n  $("szWirkBox").addEventListener("toggle", e => { if (e.target.open) szWirkZeigen(); postHeight(); });\n  box.querySelectorAll("details").forEach(d => d.addEventListener("toggle", postHeight));\n  szLabels();\n}\nfunction szLabels() {\n  for (const r of SZEN) {\n    const v = szBuch ? r.buch : szWert(r.w, SZ_POS[r.k]), el = $("sz_" + r.k);\n    $("szo_" + r.k).textContent = r.f(v); el.value = SZ_POS[r.k]; el.setAttribute("aria-valuetext", SZ_STUFE[SZ_POS[r.k]]); el.disabled = false;\n  }\n  $("szStand").textContent = "Gerechnet wird: " + szStand() + (szBuch ? ". Das ist die Rechnung des Buchs vor der Umstellung auf die wahrscheinlichsten Werte." : Object.values(SZ_POS).every(x => x === -2) || Object.values(SZ_POS).every(x => x === 2) ? ". Alles auf einmal ungünstig oder günstig ist sehr unwahrscheinlich, denn die Annahmen hängen kaum voneinander ab." : ".");\n}\nfunction szWirkZeigen() {\n  const w = szWirkung().slice(0, 5);\n  $("szWirk").innerHTML = "Staatsschulden 2070 mit Zukunftsplan, wenn nur diese eine Annahme von ungünstig auf günstig wechselt: " + w.map(x => `${x.r.nr}. ${x.r.lbl}: ${fmt(x.d * 100)} Prozentpunkte`).join("; ") + ".";\n}\nfunction szNeu(neuZeichnen = true) {\n  szAnwenden(); szUrl();\n  if (neuZeichnen) szRender(); else szLabels();\n  if ($("szWirkBox")?.open) szWirkZeigen();\n  updateAll();\n}\nfunction szInit() { szLesen(); szAnwenden(); szRender(); }\n')
rep('setForm(BEISPIELE[DEFAULT_BEISPIEL].v);',
    'szInit();\nsetForm(BEISPIELE[DEFAULT_BEISPIEL].v);')
